```tsx
import "./ButtonRow.css";

export interface ButtonRowProps {
  primaryLabel: string;
  onPrimary: () => void;
  primaryDisabled?: boolean;

  secondaryLabel: string;
  onSecondary: () => void;
  secondaryDisabled?: boolean;

  quietLabel: string;
  onQuiet: () => void;
  quietDisabled?: boolean;
}

export function ButtonRow({
  primaryLabel,
  onPrimary,
  primaryDisabled = false,
  secondaryLabel,
  onSecondary,
  secondaryDisabled = false,
  quietLabel,
  onQuiet,
  quietDisabled = false,
}: ButtonRowProps) {
  return (
    <div className="button-row" role="group" aria-label="Actions">
      <button
        type="button"
        className="button-row__button button-row__button--primary"
        onClick={onPrimary}
        disabled={primaryDisabled}
      >
        {primaryLabel}
      </button>
      <button
        type="button"
        className="button-row__button button-row__button--secondary"
        onClick={onSecondary}
        disabled={secondaryDisabled}
      >
        {secondaryLabel}
      </button>
      <button
        type="button"
        className="button-row__button button-row__button--quiet"
        onClick={onQuiet}
        disabled={quietDisabled}
      >
        {quietLabel}
      </button>
    </div>
  );
}
```

```css
.button-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: clamp(0.5rem, 1.2vw, 0.875rem);
}

.button-row__button {
  font: inherit;
  font-size: clamp(0.875rem, 0.8rem + 0.4vw, 1rem);
  line-height: 1.2;
  padding: 0.6em 1.25em;
  border-radius: 999px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease, border-color 150ms ease, box-shadow 150ms ease;
}

.button-row__button:focus-visible {
  outline: 3px solid var(--cresyl);
  outline-offset: 3px;
}

/* Primary: the main action, filled with the accent. */
.button-row__button--primary {
  background: var(--myelin);
  color: var(--slide);
  border-color: var(--myelin);
}

.button-row__button--primary:hover:not(:disabled) {
  box-shadow: 0 0 0 2px var(--myelin-wash);
}

/* Secondary: an outlined alternative. */
.button-row__button--secondary {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}

.button-row__button--secondary:hover:not(:disabled) {
  background: var(--myelin-wash);
}

/* Quiet: text only, no fill and no border. */
.button-row__button--quiet {
  padding-inline: 0.5em;
  color: var(--muted);
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 0.25em;
}

.button-row__button--quiet:hover:not(:disabled) {
  color: var(--ink);
  text-decoration-color: currentColor;
}

/* Disabled: shown with tokens only, never with opacity. */
.button-row__button:disabled {
  cursor: not-allowed;
}

.button-row__button--primary:disabled {
  background: var(--hair);
  border-color: var(--hair);
  color: var(--muted);
}

.button-row__button--secondary:disabled {
  border-color: var(--axon-ahead);
  color: var(--muted);
}

.button-row__button--quiet:disabled {
  color: var(--muted);
  text-decoration-color: transparent;
}

:root[data-motion="reduce"] .button-row__button {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .button-row__button {
    transition: none;
  }
}
```

